"""Translate the numbered/indented rows generated by NPJB00689's objectives UI.

Native 101-byte processing slots retain Japanese. Only the exact, formatted
draw strings resolve to owned English storage, preserving numbering/styles.
"""
import struct
from rengoku_runtime import require, sha
from rengoku_category_layout import wrap
from rengoku_screenshot_layout import line_width

FORMATTER = (0x1a95c8, 0x1a97f0)
FORMATTER_SHA = 'e600d9de6705e4381ed7c318e3e152bc10e27a1931b14527e8df12cd973f85f6'
TOC = 0x953f88
NUMBER_POINTERS = ((-0x4b68, 0x968d20), (-0x4b64, 0x968d28), (-0x4b60, 0x968d30))
NUMBERS = ('１．', '２．', '３．')
INDENT = '　　'
WIDTH = 950


def guard(elf):
    a, z = FORMATTER
    require(sha(elf[a-0x10000:z-0x10000]) == FORMATTER_SHA, 'Rengoku operation formatter changed')
    for (disp, address), text in zip(NUMBER_POINTERS, NUMBERS):
        require(struct.unpack_from('>I', elf, TOC+disp-0x10000)[0] == address,
                'Operation numbering pointer changed')
        p = address-0x10000
        require(elf[p:p+5] == text.encode('cp932')+b'\0', 'Operation numbering text changed')
    address = struct.unpack_from('>I', elf, TOC-0x4b5c-0x10000)[0]-0x10000
    require(elf[address:address+5] == INDENT.encode('cp932')+b'\0', 'Operation continuation indent changed')


def hooks(row, codec, fragments=None):
    jp = row['jp'].replace('\r\n', '\n')
    native = jp.split('\n')
    display = wrap(codec, row['english'], WIDTH, 32)
    english = row['english'].replace('\r\n', '\n').split('\n')
    require(len(display.split('\n')) <= 4, 'Objective exceeds four display lines')
    require(len(native) == 1 or len(native) == len(english),
            'Objective continuation needs a context-aware line adapter: '+row['id'])
    fragments = fragments or {}
    if len(native)>1:
        english=[fragments.get(source,target) for source,target in zip(native,english)]
    pairs = {jp.encode('cp932'): codec.encode(display)}
    formatted = []
    for prefix in ('', *NUMBERS):
        if len(native) == 1:
            body=wrap(codec,row['english'],WIDTH-line_width(codec,prefix,32),32)
            target = prefix + (body.replace('\n', '\n'+INDENT) if prefix else body)
        else:
            target = prefix + wrap(codec,english[0],WIDTH-line_width(codec,prefix,32),32)
        key = prefix + native[0]
        value = codec.encode(target)
        if key.encode('cp932') in pairs:
            require(pairs[key.encode('cp932')] == value, 'Ambiguous operation first line')
        pairs[key.encode('cp932')] = value
        formatted.append(dict(source=key, display=target))
    for source, target in zip(native[1:], english[1:]):
        for prefix in ('', INDENT):
            rendered=prefix+wrap(codec,target,WIDTH-line_width(codec,prefix,32),32)
            pairs[(prefix+source).encode('cp932')] = codec.encode(rendered)
            formatted.append(dict(source=prefix+source, display=rendered))
    for row_display in formatted:
        widths = [line_width(codec, line, 32) for line in row_display['display'].split('\n')]
        require(max(widths) <= WIDTH, 'Numbered objective exceeds panel width')
        row_display['line_widths'] = widths
    return pairs, dict(id=row['id'], display=display, native_source_retained=True,
                      native_lines=len(native), display_lines=len(display.split('\n')),
                      line_widths=[line_width(codec, line, 32) for line in display.split('\n')],
                      formatted=formatted, numbered_variants=3)


def merge(destination, pairs):
    for key, value in pairs.items():
        require(key not in destination or destination[key] == value,
                'Conflicting formatted condition: '+key.decode('cp932'))
        destination[key] = value
